package app.dawnbreaker.mobile;
import android.app.*;import android.content.*;import android.net.VpnService;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.yaml.snakeyaml.Yaml;import org.yaml.snakeyaml.LoaderOptions;import org.yaml.snakeyaml.constructor.SafeConstructor;import io.github.oviron.libmihomo.*;
public class DawnWarpService extends VpnService{
 static volatile boolean running=false;static volatile String error="";static String secret="",name="",mode="rule";static int port,mixed;private static DawnWarpService instance;
 static File root(Context c){File f=new File(c.getFilesDir(),"warp");f.mkdirs();return f;}
 static int free()throws Exception{try(ServerSocket s=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){return s.getLocalPort();}}
 @SuppressWarnings("unchecked") static synchronized void prepare(Context context,JSONObject o)throws Exception{
  if(running){stop(context);Thread.sleep(300);}error="";String text=o.optString("yaml"),subscription=o.optString("subscription");if(!subscription.isEmpty()){URL u=new URL(subscription);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null)throw new Exception("订阅需为 HTTPS 地址");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","clash.meta/DawnBreaker");try(InputStream in=c.getInputStream()){text=new String(read(in,1000000),StandardCharsets.UTF_8);}finally{c.disconnect();}}
  LoaderOptions limits=new LoaderOptions();limits.setMaxAliasesForCollections(20);limits.setCodePointLimit(1000000);Object parsed=new Yaml(new SafeConstructor(limits)).load(text);if(!(parsed instanceof Map))throw new Exception("需要有效的 Clash YAML 配置");Map<String,Object> config=(Map<String,Object>)parsed;
  for(String key:Arrays.asList("external-ui","external-ui-url","external-ui-name","external-controller-unix","external-controller-pipe","external-controller-cors","external-controller-tls","tls","profile","authentication","listeners","interface-name","routing-mark"))config.remove(key);
  for(String key:Arrays.asList("proxy-providers","rule-providers")){Object providers=config.get(key);if(providers instanceof Map)for(Object k:((Map<?,?>)providers).keySet()){Object v=((Map<?,?>)providers).get(k);if(v instanceof Map)((Map<String,Object>)v).put("path",new File(root(context),"provider-"+UUID.randomUUID()+".yaml").getAbsolutePath());}}
  port=free();mixed=free();secret=UUID.randomUUID().toString();name=o.optString("name","本地配置");config.put("allow-lan",false);config.put("bind-address","127.0.0.1");config.put("mixed-port",mixed);for(String key:Arrays.asList("port","socks-port","redir-port","tproxy-port"))config.put(key,0);config.remove("external-controller");mode=String.valueOf(config.getOrDefault("mode","rule"));config.put("secret",secret);config.put("tun",Collections.singletonMap("enable",false));config.put("log-level","silent");Object dns=config.get("dns");if(dns instanceof Map)((Map<String,Object>)dns).put("listen","127.0.0.1:0");
  try(FileOutputStream out=new FileOutputStream(new File(root(context),"config.yaml"))){out.write(new Yaml().dump(config).getBytes(StandardCharsets.UTF_8));}
 }
 static byte[] read(InputStream in,int limit)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[16384];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new Exception("文件超过大小限制");out.write(b,0,n);}return out.toByteArray();}
 static JSONObject request(String route,String method,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://127.0.0.1:"+port+route).openConnection();c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+secret);c.setConnectTimeout(6000);c.setReadTimeout(7000);try{if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}if(c.getResponseCode()>=300)throw new Exception("核心请求失败");if(c.getResponseCode()==204)return new JSONObject();try(InputStream in=c.getInputStream()){return new JSONObject(new String(read(in,4*1024*1024),StandardCharsets.UTF_8));}}finally{c.disconnect();}}
 static String enc(String s)throws Exception{return java.net.URLEncoder.encode(s,"UTF-8").replace("+","%20");}
 static Object invoke(String method,Object data)throws Exception{CountDownLatch done=new CountDownLatch(1);String[] value={""};Clash.INSTANCE.invokeAction(new JSONObject().put("id",UUID.randomUUID().toString()).put("method",method).put("data",data).toString(),(InvokeInterface)result->{value[0]=result;done.countDown();});if(!done.await(12,TimeUnit.SECONDS))throw new Exception("核心请求超时");JSONObject result=new JSONObject(value[0]);if(result.optInt("code")!=0)throw new Exception("核心请求失败");return result.opt("data");}
 static JSONObject action(Context c,String command,JSONObject o)throws Exception{switch(command){case"warp.stop":stop(c);return status();case"warp.status":return status();case"warp.select":invoke("changeProxy",new JSONObject().put("group-name",o.getString("group")).put("proxy-name",o.getString("name")).toString());return status();case"warp.mode":String m=o.optString("mode");if(!Arrays.asList("rule","global","direct").contains(m))throw new Exception("模式无效");Object updated=invoke("updateConfig",new JSONObject().put("mode",m).toString());if(updated instanceof String&&!((String)updated).isEmpty())throw new Exception("模式切换失败");mode=m;return status();case"warp.delay":Object delay=invoke("testDelay",new JSONObject().put("proxy-name",o.getString("name")).put("test-url","https://www.gstatic.com/generate_204").put("timeout",5000).toString());return new JSONObject().put("delay",delay);default:throw new Exception("未知核心操作");}}
 static JSONObject status()throws Exception{JSONObject result=new JSONObject().put("running",running).put("error",error).put("profile",name).put("mixed_port",mixed).put("mode",mode).put("core","Mihomo v1.19.33").put("proxies",new JSONObject()).put("traffic",new JSONObject());if(running)try{Object proxies=invoke("getProxies","");JSONObject p=proxies instanceof String?new JSONObject((String)proxies):(JSONObject)proxies;result.put("proxies",p.optJSONObject("proxies"));JSONObject t=new JSONObject(Clash.INSTANCE.getTotalTraffic());result.put("traffic",new JSONObject().put("up",t.optLong("up")).put("down",t.optLong("down")));}catch(Exception ignored){}return result;}
 static void stop(Context c){if(instance!=null){try{Clash.INSTANCE.stopTun();}catch(Throwable ignored){}running=false;if(Build.VERSION.SDK_INT>=24)instance.stopForeground(STOP_FOREGROUND_REMOVE);else instance.stopForeground(true);instance.stopSelf();}c.stopService(new Intent(c,DawnWarpService.class));}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(running)return START_NOT_STICKY;instance=this;NotificationManager manager=getSystemService(NotificationManager.class);if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel("dawn-vpn","折跃门连接",NotificationManager.IMPORTANCE_LOW));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification notification=new androidx.core.app.NotificationCompat.Builder(this,"dawn-vpn").setSmallIcon(android.R.drawable.stat_sys_warning).setContentTitle("折跃门").setContentText("设备代理正在运行").setContentIntent(open).setOngoing(true).build();if(Build.VERSION.SDK_INT>=34)startForeground(7301,notification,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(7301,notification);
  new Thread(()->{try{Clash.INSTANCE.load(getApplicationInfo().nativeLibraryDir);Clash.INSTANCE.assertReady();CountDownLatch latch=new CountDownLatch(1);String[] result={""};Clash.INSTANCE.quickSetup(new JSONObject().put("home-dir",root(this).getAbsolutePath()).put("version",Build.VERSION.SDK_INT).toString(),new JSONObject().toString(),(InvokeInterface)value->{result[0]=value;latch.countDown();});if(!latch.await(30,TimeUnit.SECONDS)||result[0]!=null&&!result[0].isEmpty())throw new Exception("配置加载失败，请检查节点与规则");
   android.os.ParcelFileDescriptor fd=new Builder().setSession("破晓 · 折跃门").addAddress("172.19.0.1",30).addRoute("0.0.0.0",0).addDnsServer("1.1.1.1").addAddress("fdfe:dcba:9876::1",126).addRoute("::",0).setMtu(1400).establish();if(fd==null)throw new Exception("系统未能建立 VPN");Clash.INSTANCE.startTUN(fd.detachFd(),new TunInterface(){public void protect(int socket){DawnWarpService.this.protect(socket);}public String resolverProcess(int protocol,String source,String target,int uid){String[] p=getPackageManager().getPackagesForUid(uid);return p==null||p.length==0?"":p[0];}},"dawn-tun","gvisor","172.19.0.1/30,fdfe:dcba:9876::1/126","1.1.1.1",1400);running=true;
  }catch(Throwable e){error=e.getMessage()==null?"VPN 核心启动失败":e.getMessage();stop(this);}},"dawn-vpn-init").start();return START_NOT_STICKY;}
 @Override public void onRevoke(){stop(this);super.onRevoke();}@Override public void onDestroy(){running=false;try{if(Clash.INSTANCE.isLoaded())Clash.INSTANCE.stopTun();}catch(Throwable ignored){}instance=null;super.onDestroy();}
}
